import numpy as np
import numba as nb

INF = 1e300


@nb.njit(cache=True)
def duals(C):
    n, m = C.shape
    v = np.full(m, INF)
    for i in range(n):
        for j in range(m):
            if C[i, j] < v[j]:
                v[j] = C[i, j]
    u = np.empty(n)
    for i in range(n):
        mn = INF
        for j in range(m):
            r = C[i, j] - v[j]
            if r < mn:
                mn = r
        u[i] = mn
    return u, v


@nb.njit(cache=True)
def build(C, u, v, tau):
    n = C.shape[0]
    cnt = np.zeros(n + 1, np.int64)
    for i in range(n):
        c = 0
        ui = u[i] + tau
        for j in range(n):
            if C[i, j] - v[j] <= ui:
                c += 1
        cnt[i + 1] = cnt[i] + c
    ind = np.empty(cnt[n], np.int64)
    cst = np.empty(cnt[n])
    for i in range(n):
        p = cnt[i]
        ui = u[i] + tau
        for j in range(n):
            if C[i, j] - v[j] <= ui:
                ind[p] = j
                cst[p] = C[i, j]
                p += 1
    return cnt, ind, cst


@nb.njit(cache=True)
def auction(n, ptr, ind, cst, p, eps0, eps_min, factor, maxbids):
    x = -np.ones(n, np.int64)
    y = -np.ones(n, np.int64)
    free = np.empty(n, np.int64)
    eps = eps0
    total = 0
    while True:
        for i in range(n):
            x[i] = -1
        for j in range(n):
            y[j] = -1
        for i in range(n):
            free[i] = n - 1 - i
        nf = n
        while nf > 0:
            nf -= 1
            i = free[nf]
            b1 = INF
            b2 = INF
            j1 = -1
            for q in range(ptr[i], ptr[i + 1]):
                j = ind[q]
                w = cst[q] + p[j]
                if w < b2:
                    if w < b1:
                        b2 = b1
                        b1 = w
                        j1 = j
                    else:
                        b2 = w
            if b2 >= INF:
                b2 = b1 + eps0
            p[j1] += (b2 - b1) + eps
            old = y[j1]
            y[j1] = i
            x[i] = j1
            if old >= 0:
                x[old] = -1
                free[nf] = old
                nf += 1
            total += 1
            if total > maxbids:
                return x, y, False
        if eps <= eps_min:
            break
        eps = max(eps * factor, eps_min)
    return x, y, True


@nb.njit(cache=True)
def certify(C, x, y, v, maxscan, tol):
    n = C.shape[0]
    inq = np.ones(n, np.bool_)
    qs = n + 1
    q = np.empty(qs, np.int64)
    head = 0
    tail = 0
    for i in range(n):
        q[tail] = i
        tail += 1
    scans = 0
    while head != tail:
        i = q[head]
        head += 1
        if head == qs:
            head = 0
        inq[i] = False
        scans += 1
        if scans > maxscan:
            return False, scans
        xi = x[i]
        ui = C[i, xi] - v[xi] - tol
        for j in range(n):
            r = C[i, j] - v[j]
            if r < ui and j != xi:
                v[j] = C[i, j] - ui - tol
                k = y[j]
                if not inq[k]:
                    inq[k] = True
                    q[tail] = k
                    tail += 1
                    if tail == qs:
                        tail = 0
                ui = C[i, xi] - v[xi] - tol
    return True, scans


def solve_assign(C, k=30):
    n = C.shape[0]
    u, v = duals(C)
    R = (C[::7, ::3] - u[::7, None] - v[None, ::3]).ravel()
    idx = min(len(R) - 1, int(len(R) * k / n))
    tau = np.partition(R, idx)[idx]
    ptr, ind, cst = build(C, u, v, tau)
    p = -v.copy()
    x, y, ok = auction(n, ptr, ind, cst, p, tau / 2, 1e-11, 0.2, 200 * n * 20)
    if not ok:
        return None, 'auction'
    vv = -p
    ok, sc = certify(C, x, y, vv, 30 * n, 1e-13)
    if not ok:
        return None, 'cert'
    return x, (len(ind), sc)
